// Copies README.md and examples/*/README.md into the VitePress source tree
// (docs/guide, docs/examples) so the originals stay the source of truth.
// Generated files are gitignored. Relative links are rewritten to site pages
// where one exists, otherwise to the file on GitHub.
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, posix, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const REPO = 'https://github.com/CoderCoco/cohost';
const BASE = ''; // VitePress prepends base (docs/.vitepress/config.ts) to root-relative links

/** repo-relative source path -> repo-relative generated page (under docs/). */
const pages = new Map([
  ['README.md', 'guide/index.md'],
  ['examples/README.md', 'examples/index.md'],
]);
for (const d of readdirSync(join(root, 'examples'), { withFileTypes: true })) {
  if (d.isDirectory() && existsSync(join(root, 'examples', d.name, 'README.md'))) {
    pages.set(`examples/${d.name}/README.md`, `examples/${d.name}.md`);
  }
}
// Hand-written pages that live in docs/ already.
const native = new Map([
  ['docs/TESTING.md', 'TESTING'],
  ['docs/SPEC-DRIVEN.md', 'SPEC-DRIVEN'],
]);

function sitePath(page) {
  return `${BASE}/${page.replace(/index\.md$/, '').replace(/\.md$/, '')}`;
}

function rewrite(src, text) {
  return text.replace(/(\]\()([^)\s]+)(\))/g, (m, open, href, close) => {
    if (/^([a-z][a-z0-9+.-]*:|#|\/)/i.test(href)) return m;
    const [path, hash = ''] = href.split('#');
    const target = posix.normalize(posix.join(posix.dirname(src), path));
    const suffix = hash ? `#${hash}` : '';
    const stripped = target.replace(/\/$/, '');
    if (pages.has(stripped) || pages.has(`${stripped}/README.md`)) {
      return `${open}${sitePath(pages.get(stripped) ?? pages.get(`${stripped}/README.md`))}${suffix}${close}`;
    }
    if (native.has(stripped)) return `${open}${BASE}/${native.get(stripped)}${suffix}${close}`;
    const isDir = target.endsWith('/') || !/\.[a-z0-9]+$/i.test(stripped);
    return `${open}${REPO}/${isDir ? 'tree' : 'blob'}/main/${stripped}${suffix}${close}`;
  });
}

for (const dir of ['guide', 'examples']) rmSync(join(root, 'docs', dir), { recursive: true, force: true });
for (const [src, page] of pages) {
  const out = join(root, 'docs', page);
  mkdirSync(dirname(out), { recursive: true });
  const banner = `<!-- Generated by scripts/docs-prepare.mjs from ${src}. Edit the source, not this file. -->\n\n`;
  writeFileSync(out, banner + rewrite(src, readFileSync(join(root, src), 'utf8')));
  console.log(`${src} -> docs/${relative(join(root, 'docs'), out)}`);
}
